import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"精灵主题、五态变体与基础 Renderer","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.1/ui/index.md","filePath":"1.21.1/ui/index.md"}'),i={name:"1.21.1/ui/index.md"};function a(r,e,s,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="精灵主题、五态变体与基础-renderer" tabindex="-1">精灵主题、五态变体与基础 Renderer <a class="header-anchor" href="#精灵主题、五态变体与基础-renderer" aria-label="Permalink to &quot;精灵主题、五态变体与基础 Renderer&quot;">​</a></h1><p><code>module.ui</code>（模组 ID：<code>anvillib_ui</code>）为 NeoForge 1.21.1 提供了轻量级的<strong>客户端柔性控件渲染库（<code>dev.anvilcraft.lib.v2.ui.flexible</code>）</strong>，通过九宫格精灵切图查找表（<code>FlexibleSprites</code>）与**“配置态渲染器 (<code>Renderer</code>) + 帧作用域 (<code>Scope</code>)”**分离模型，轻松绘制自适应文本宽高的 3D/扁平按钮、双主题开关与带方向指示箭头的浮窗（Flyout）。</p><h2 id="接入配置" tabindex="-1">接入配置 <a class="header-anchor" href="#接入配置" aria-label="Permalink to &quot;接入配置&quot;">​</a></h2><h3 id="gradle-仓库与依赖" tabindex="-1">Gradle 仓库与依赖 <a class="header-anchor" href="#gradle-仓库与依赖" aria-label="Permalink to &quot;Gradle 仓库与依赖&quot;">​</a></h3><p>正式版可从 Maven Central 获取，但推荐使用 <code>Cjsah Maven</code> 仓库并通过 <code>exclusiveContent</code> 过滤组，以避免 NeoForge Maven 未完全同步 Maven Central 导致接口注入或传递元数据异常：</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repositories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    exclusiveContent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        forRepository</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">            maven</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://server.cjsah.net:1002/maven/releases&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cjsah Maven&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">            includeGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    mavenCentral</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    implementation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib:anvillib-neoforge-1.21.1:${anvillib_version}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="入口与客户端限制" tabindex="-1">入口与客户端限制 <a class="header-anchor" href="#入口与客户端限制" aria-label="Permalink to &quot;入口与客户端限制&quot;">​</a></h3><ul><li><strong><code>AnvilLibUi</code></strong>：使用 <code>@Mod(value = AnvilLibUi.MOD_ID, dist = Dist.CLIENT)</code> 标记（<code>MOD_ID = &quot;anvillib_ui&quot;</code>），提供静态辅助方法 <code>AnvilLibUi.of(String path)</code> 生成 <code>anvillib_ui:&lt;path&gt;</code> 资源定位符。</li><li>模块内所有类均属于客户端渲染域，仅可在 <code>Dist.CLIENT</code> 渲染路径使用。</li></ul><h2 id="设计思想-四维精灵查表与-scope-生命周期" tabindex="-1">设计思想：四维精灵查表与 Scope 生命周期 <a class="header-anchor" href="#设计思想-四维精灵查表与-scope-生命周期" aria-label="Permalink to &quot;设计思想：四维精灵查表与 Scope 生命周期&quot;">​</a></h2><h3 id="_1-四维组合定位九宫格切图" tabindex="-1">1. 四维组合定位九宫格切图 <a class="header-anchor" href="#_1-四维组合定位九宫格切图" aria-label="Permalink to &quot;1. 四维组合定位九宫格切图&quot;">​</a></h3><p>所有内置柔性控件切图路径均为 <code>anvillib_ui:flex_button/&lt;theme&gt;&lt;style&gt;&lt;type&gt;&lt;variant&gt;</code>，由 4 个正交枚举唯一决定：</p><table tabindex="0"><thead><tr><th>维度</th><th>枚举类</th><th>可选值与路径段 (<code>getPath()</code>)</th><th>设计语义</th></tr></thead><tbody><tr><td><strong>主题</strong></td><td><code>SpriteTheme</code></td><td><code>LIGHT</code> (<code>&quot;&quot;</code>)、<code>DARK</code> (<code>&quot;dark&quot;</code>)</td><td>亮色/暗色底板配色方案</td></tr><tr><td><strong>风格</strong></td><td><code>SpriteStyle</code></td><td><code>THREE_D</code> (<code>&quot;&quot;</code>)、<code>FLAT</code> (<code>&quot;flat&quot;</code>)</td><td>立体 bevel 边框风格 / 扁平风格</td></tr><tr><td><strong>阴影</strong></td><td><code>SpriteType</code></td><td><code>NON_SHADED</code>、<code>SHADED_1PX</code>、<code>SHADED_2PX</code></td><td>控制底边投影像素；按压态时底部阴影自动转换为顶部加厚以体现“下沉感”</td></tr><tr><td><strong>状态</strong></td><td><code>SpriteVariant</code></td><td><code>NORMAL</code> (<code>&quot;&quot;</code>)、<code>HIGHLIGHTED</code>、<code>PRESSED</code>、<code>HIGHLIGHTED_PRESSED</code>、<code>HIGHLIGHTED_PRESSING</code></td><td>常态、悬停、已选中、选中且悬停、悬停正按住</td></tr></tbody></table><p><code>FlexibleSprites</code> 在类静态初始化时即一次性算出全部四维组合对应的九宫格内边距（<code>left/top/right/bottomPadding</code>）及顶部朝上指针所需下移补偿（<code>pointerUpInset = max(0, topPadding - 2)</code>），避免逐帧分配。</p><h3 id="_2-renderer-与-scope-的生命周期分离" tabindex="-1">2. <code>Renderer</code> 与 <code>Scope</code> 的生命周期分离 <a class="header-anchor" href="#_2-renderer-与-scope-的生命周期分离" aria-label="Permalink to &quot;2. `Renderer` 与 `Scope` 的生命周期分离&quot;">​</a></h3><ul><li><strong><code>Renderer&lt;T extends Scope&gt;</code></strong>（长生命周期）：持有一个控件的外观设定（主题、样式、类型、按钮交互模式、切换状态回调 <code>BooleanSupplier</code>、鼠标按压起点与当前渐变透明度 <code>alpha</code>），可以作为 <code>Screen</code> 字段跨帧复用。</li><li><strong><code>Renderer.Scope</code></strong>（单帧短生命周期，实现 <code>AutoCloseable</code>）：绑定单次绘制才确定的动态上下文（<code>GuiGraphics</code>、<code>pos</code>、<code>size</code> / <code>flexSize</code>、<code>mousePos</code>、<code>font</code>、<code>text</code>、<code>textOffset</code>）。 <ul><li><strong>推荐写法</strong>：在每帧使用 <code>try (var scope = renderer.open()) { ... scope.render(); }</code>。退出作用域时 <code>close()</code> 会自动将 <code>graphics</code>、<code>font</code>、<code>text</code> 等引用全部置空，防止 <code>GuiGraphics</code> 或临时组件泄漏到帧外。</li><li><strong>按压/点击判定循环防护</strong>：<code>flexSize(...)</code> 会为尺寸解析单独生成“绑定当前变体”的绘制尺寸函数 <code>size</code> 与“固定用 <code>NORMAL</code> 常态计算”的命中盒函数 <code>hitSize</code>，避免 <code>basedOnMouse</code> 在计算变体时反过来调用 <code>contains</code> -&gt; 再读 <code>size</code> -&gt; 又求变体造成的无限递归。也正因如此，带阴影按钮按下时视觉底部下沉 1px，其命中检测盒仍保持 <code>NORMAL</code> 态高度，符合原版手风琴防抖交互逻辑。</li></ul></li></ul><h2 id="公开-api-完整参考" tabindex="-1">公开 API 完整参考 <a class="header-anchor" href="#公开-api-完整参考" aria-label="Permalink to &quot;公开 API 完整参考&quot;">​</a></h2><h3 id="_1-anvillibui" tabindex="-1">1. <code>AnvilLibUi</code> <a class="header-anchor" href="#_1-anvillibui" aria-label="Permalink to &quot;1. `AnvilLibUi`&quot;">​</a></h3><p>包名：<code>dev.anvilcraft.lib.v2.ui</code></p><table tabindex="0"><thead><tr><th>成员签名</th><th>说明</th></tr></thead><tbody><tr><td><code>public static final String MOD_ID = &quot;anvillib_ui&quot;</code></td><td>模块 Mod ID</td></tr><tr><td><code>static ResourceLocation of(String path)</code></td><td>创建 <code>anvillib_ui:&lt;path&gt;</code> 资源定位符</td></tr></tbody></table><h3 id="_2-基础枚举与-flexiblesprites" tabindex="-1">2. 基础枚举与 <code>FlexibleSprites</code> <a class="header-anchor" href="#_2-基础枚举与-flexiblesprites" aria-label="Permalink to &quot;2. 基础枚举与 `FlexibleSprites`&quot;">​</a></h3><p>包名：<code>dev.anvilcraft.lib.v2.ui.flexible</code></p><table tabindex="0"><thead><tr><th>类型 / 方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>enum SpriteTheme</code> (<code>LIGHT</code>, <code>DARK</code>)</td><td>提供 <code>getPath()</code> (<code>&quot;&quot;</code> / <code>&quot;dark&quot;</code>)</td></tr><tr><td><code>enum SpriteStyle</code> (<code>THREE_D</code>, <code>FLAT</code>)</td><td>提供 <code>getPath()</code> (<code>&quot;&quot;</code> / <code>&quot;flat&quot;</code>)</td></tr><tr><td><code>enum SpriteType</code> (<code>NON_SHADED</code>, <code>SHADED_1PX</code>, <code>SHADED_2PX</code>)</td><td>提供 <code>getPath()</code> (<code>&quot;non_shaded&quot;</code> / <code>&quot;shaded_1px&quot;</code> / <code>&quot;shaded_2px&quot;</code>)</td></tr><tr><td><code>enum SpriteVariant</code> (<code>NORMAL</code>, <code>HIGHLIGHTED</code>, <code>PRESSED</code>, <code>HIGHLIGHTED_PRESSED</code>, <code>HIGHLIGHTED_PRESSING</code>)</td><td>提供 <code>getPath()</code></td></tr><tr><td><code>enum PointerDirection</code> (<code>LEFT</code>, <code>RIGHT</code>, <code>UP</code>, <code>DOWN</code>)</td><td>提供 <code>getPath()</code> (<code>&quot;left&quot;</code> / <code>&quot;right&quot;</code> / <code>&quot;up&quot;</code> / <code>&quot;down&quot;</code>)</td></tr><tr><td><code>static SpriteInfo FlexibleSprites.pickSprite(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant)</code></td><td>返回精确匹配的本体贴图与内边距 <code>SpriteInfo</code></td></tr><tr><td><code>static @Nullable PointerSprite FlexibleSprites.pickPointer(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant, PointerDirection)</code></td><td>按组合名读取并缓存 <code>textures/gui/pointer/...png</code> 原始尺寸（剔除四周各 <code>1px</code> 透明边距后的可见内容宽高）；缺失对应变体贴图时返回 <code>null</code></td></tr><tr><td><code>record SpriteInfo(ResourceLocation sprite, int leftPadding, int topPadding, int rightPadding, int bottomPadding, int pointerUpInset)</code></td><td>另提供 5 参兼容构造器（默认 <code>pointerUpInset = 0</code>）</td></tr><tr><td><code>record PointerSprite(ResourceLocation texture, int width, int height, int pointerUpInset)</code></td><td>指针纹理路径与可见像素尺寸描述</td></tr></tbody></table><h3 id="_3-renderer-t-extends-renderer-t-scope-renderer-scope" tabindex="-1">3. <code>Renderer&lt;T extends Renderer&lt;T&gt;.Scope&gt;</code> &amp; <code>Renderer.Scope</code> <a class="header-anchor" href="#_3-renderer-t-extends-renderer-t-scope-renderer-scope" aria-label="Permalink to &quot;3. `Renderer&lt;T extends Renderer&lt;T&gt;.Scope&gt;` &amp; `Renderer.Scope`&quot;">​</a></h3><p>包名：<code>dev.anvilcraft.lib.v2.ui.flexible</code></p><h4 id="renderer-t-外观与交互配置方法" tabindex="-1"><code>Renderer&lt;T&gt;</code> 外观与交互配置方法 <a class="header-anchor" href="#renderer-t-外观与交互配置方法" aria-label="Permalink to &quot;`Renderer&lt;T&gt;` 外观与交互配置方法&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>getTheme()</code> / <code>getStyle()</code> / <code>getType()</code> / <code>getAlpha()</code></td><td>Lombok <code>@Getter</code> 属性读取器</td></tr><tr><td><code>Renderer&lt;T&gt; dark()</code></td><td>切换为暗色主题 <code>SpriteTheme.DARK</code></td></tr><tr><td><code>Renderer&lt;T&gt; flat()</code></td><td>切换为扁平风格 <code>SpriteStyle.FLAT</code></td></tr><tr><td><code>Renderer&lt;T&gt; shaded1px()</code> / <code>shaded2px()</code></td><td>切换为 <code>SHADED_1PX</code> / <code>SHADED_2PX</code> 阴影类型</td></tr><tr><td><code>Renderer&lt;T&gt; highlighted()</code> / <code>pressed()</code> / <code>highlightedPressed()</code> / <code>highlightedPressing()</code></td><td>固定当前渲染器始终使用对应静态变体（覆盖鼠标推导行为）</td></tr><tr><td><code>Renderer&lt;T&gt; buttonType(ButtonType buttonType)</code></td><td>设置按钮交互模式（默认 <code>ButtonType.DISPLAY</code>）</td></tr><tr><td><code>Renderer&lt;T&gt; toggleState(BooleanSupplier toggleState)</code></td><td>绑定 <code>ButtonType.TOGGLE</code> 使用的选中状态数据源（默认 <code>() -&gt; false</code>）</td></tr><tr><td><code>Renderer&lt;T&gt; alpha(float alpha)</code></td><td>设置整体透明度并钳制至 <code>[0.0F, 1.0F]</code>；传入 <code>NaN</code> 时自动忽略以防淡入淡出异常闪烁</td></tr><tr><td><code>Renderer&lt;T&gt; basedOnMouse()</code></td><td>启用鼠标自适应交互（允许左键与右键触发按压反馈）</td></tr><tr><td><code>Renderer&lt;T&gt; basedOnMouse(IntSet allowedKeys)</code></td><td>启用鼠标自适应交互并自定义允许按压触发的 GLFW 鼠标按键码集合</td></tr><tr><td><code>void onPress(int x, int y)</code> / <code>onPress(Vector2f pos)</code></td><td>在 <code>Screen#mouseClicked</code> 中调用，记录鼠标按下瞬间的起点位置</td></tr><tr><td><code>void onRelease()</code></td><td>在 <code>Screen#mouseReleased</code> 中调用，清除按压起点记录</td></tr><tr><td><code>SpriteVariant variantOf(T scope)</code></td><td>在不执行实际绘制的情况下提前求值当前作用域采用的 <code>SpriteVariant</code></td></tr><tr><td><code>abstract T open()</code></td><td>打开一个单帧绘制作用域</td></tr></tbody></table><h4 id="renderer-scope-链式配置与绘制方法-implements-autocloseable" tabindex="-1"><code>Renderer.Scope</code> 链式配置与绘制方法 (<code>implements AutoCloseable</code>) <a class="header-anchor" href="#renderer-scope-链式配置与绘制方法-implements-autocloseable" aria-label="Permalink to &quot;`Renderer.Scope` 链式配置与绘制方法 (`implements AutoCloseable`)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>Scope graphics(GuiGraphics graphics)</code></td><td>绑定本帧的 <code>GuiGraphics</code>（必填）</td></tr><tr><td><code>Scope font(Font font)</code></td><td>绑定绘制文本与计算 <code>flexSize</code> 所需的字体实例</td></tr><tr><td><code>Scope pos(int x, int y)</code> / <code>pos(Vector2i pos)</code></td><td>设置左上角像素坐标（必填）</td></tr><tr><td><code>Scope mousePos(int x, int y)</code> / <code>mousePos(Vector2f pos)</code></td><td>绑定当前帧鼠标坐标（当 <code>basedOnMouse</code> 且非 <code>DISPLAY</code> 时必填）</td></tr><tr><td><code>Scope size(int width, int height)</code> / <code>size(Vector2i size)</code></td><td>手动指定固定矩形宽高（与 <code>flexSize</code> 互斥，二者必填其一）</td></tr><tr><td><code>Scope flexSize(int padding)</code> / <code>(horizontalPadding, verticalPadding)</code> / <code>(left, top, right, bottom)</code></td><td>根据 <code>font</code> 与 <code>text</code> 尺寸加上指定内边距以及当前贴图边框厚度自适应计算宽高，同时自动设置对应的 <code>textOffset</code></td></tr><tr><td><code>Scope literal(String)</code> / <code>translatable(...)</code> / <code>translatableWithFallback(...)</code> / <code>text(Component)</code></td><td>设置绘制与测算使用的文本组件</td></tr><tr><td><code>Scope textOffset(int x, int y)</code> / <code>textOffset(Vector2i)</code></td><td>手动指定文字相对控件左上角内边线内的追加偏移（注意 <code>flexSize</code> 会自动写入该值，如需微调应在 <code>flexSize</code> <strong>之后</strong>调用）</td></tr><tr><td><code>@Nullable Vector2i resolveSize()</code></td><td>返回当前解析到的渲染宽高；若尚未调用 <code>size</code>/<code>flexSize</code> 则返回 <code>null</code></td></tr><tr><td><code>boolean contains(@Nullable Vector2f point)</code></td><td>判断坐标点是否落在本控件命中区域内（使用 <code>hitSize</code> 计算）</td></tr><tr><td><code>Scope render()</code></td><td>校验所有必填字段（缺漏会抛 <code>IllegalStateException</code>）后执行子类绘制并返回 <code>this</code></td></tr><tr><td><code>void close()</code></td><td>清空本帧持有的对象引用，释放作用域</td></tr></tbody></table>',28)])])}const g=t(i,[["render",a]]);export{u as __pageData,g as default};
